happiness = 5

while happiness > 0 and happiness < 10:
    action = input("What do you do? (play/feed/sleep) ")
    if action == "play":
        happiness = happiness + 2
        print("Your pet is happy! Happiness:", happiness)
    elif action == "feed":
        happiness = happiness + 1
    else:
        print("Your pet is confused.")
